const emptyLine = () => new Paragraph({ spacing: { after: 0, line: LINE_SPACING }, children: [] });
const pageBreak = () => new Paragraph({ children: [new PageBreak()] });

const makeCell = (text, opts = {}) => new TableCell({
  width: { size: opts.w || Math.floor(PAGE_W / 3), type: WidthType.DXA },
  borders: {
    top: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
    bottom: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
    left: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
    right: { style: BorderStyle.SINGLE, size: 1, color: "000000" }
  },
  children: [new Paragraph({
    spacing: { after: 0, line: 240 },
    children: [new TextRun({ text, bold: !!opts.bold, size: 22, font: FONT })]
  })]
});

const makeRow = (cells, isHeader, widths) => new TableRow({
  children: cells.map((c, i) => makeCell(c, {
    bold: isHeader,
    w: widths ? widths[i] : Math.floor(PAGE_W / cells.length)
  }))
});

const makeTable = (headers, rows, widths) => {
  const cols = widths || headers.map(() => Math.floor(PAGE_W / headers.length));
  return new Table({
    width: { size: PAGE_W, type: WidthType.DXA },
    columnWidths: cols,
    rows: [
      makeRow(headers, true, widths),
      ...rows.map(r => makeRow(r, false, widths))
    ]
  });
};

const FIG_DIR = "D:\\Share\\diplom\\v1\\\u0412\u041a\u0420\\\u0414\u0438\u0430\u0433\u0440\u0430\u043c\u043c\u044b\\png";

const pngSize = (buf) => {
  const w = buf.readUInt32BE(16);
  const h = buf.readUInt32BE(20);
  return { w, h };
};

const figImage = (fileName) => {
  const path = FIG_DIR + "\\" + fileName;
  const buf = fs.readFileSync(path);
  const { w, h } = pngSize(buf);
  const maxW = 580;
  const maxH = 620;
  const scale = Math.min(maxW / w, maxH / h, 1);
  const width = Math.round(w * scale);
  const height = Math.round(h * scale);
  return new Paragraph({
    spacing: { before: 80, after: 0, line: LINE_SPACING },
    alignment: AlignmentType.CENTER,
    children: [
      new ImageRun({ data: buf, transformation: { width, height }, type: "png" })
    ]
  });
};

